const candidate = {
  name: $json.candidateName,
  skills: String($json.skills ?? "")
    .split(",")
    .map(s => s.trim().toLowerCase())
    .filter(Boolean),
  preferredRole: $json.preferredRole,
  interests: String($json.interests ?? "")
    .split(",")
    .map(s => s.trim())
    .filter(Boolean)
};

const jobs = [
  {
    title: "AI Intern",
    company: "Example AI Company",
    skills: ["Python", "Machine Learning", "SQL"]
  },
  {
    title: "Web Development Intern",
    company: "Example Web Company",
    skills: ["HTML", "CSS", "JavaScript"]
  },
  {
    title: "Data Analyst Intern",
    company: "Example Data Company",
    skills: ["Python", "SQL", "Excel"]
  }
];

return jobs.map(job => {
  const matchedSkills = job.skills.filter(skill =>
    candidate.skills.includes(skill.toLowerCase())
  );

  const missingSkills = job.skills.filter(
    skill => !matchedSkills.includes(skill)
  );

  return {
    json: {
      candidate: candidate.name,
      preferredRole: candidate.preferredRole,
      jobTitle: job.title,
      company: job.company,
      requiredSkills: job.skills,
      matchedSkills,
      missingSkills,
      matchPercentage: Math.round(
        (matchedSkills.length / job.skills.length) * 100
      )
    }
  };
});

const results = $input.all().map(item => item.json);

const escapeHtml = value => String(value ?? "").replace(/[&<>"']/g, char => ({
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;"
}[char]));

const firstJob = results[0] || {};
const preferredRole = firstJob.preferredRole || "your preferred role";

// Collect missing skills from all job matches without duplicates.
const allMissing = [...new Set(
  results.flatMap(job => job.missingSkills || [])
)];

const allMatched = [...new Set(
  results.flatMap(job => job.matchedSkills || [])
)];

const roleText = String(preferredRole).toLowerCase();

// Choose project ideas based on the preferred role.
let projects;

if (/data|analyst/.test(roleText)) {
  projects = [
    "Student Performance Analysis using Python and Excel",
    "Sales Data Dashboard using SQL and a charting tool"
  ];
} else if (/web|frontend|front-end/.test(roleText)) {
  projects = [
    "Personal Portfolio Website using HTML and CSS",
    "Task Tracker using JavaScript"
  ];
} else if (/ai|machine learning|ml/.test(roleText)) {
  projects = [
    "Student Score Prediction using Python",
    "Simple Movie Recommendation System"
  ];
} else {
  projects = [
    "Personal Portfolio Website showcasing your skills",
    "Student Task Tracker with a simple progress report"
  ];
}

// Build a roadmap using the candidate's actual missing skills.
const roadmap = [];

if (allMissing.length === 0) {
  roadmap.push(
    ["Week 1", "Revise your existing skills and practise fundamentals."],
    ["Week 2", "Build a small project using your strongest skills."],
    ["Week 3", "Improve the project and document how it works."],
    ["Week 4", "Practise interview questions and prepare your portfolio."]
  );
} else {
  const skillGroups = [
    allMissing.slice(0, 2),
    allMissing.slice(2, 4),
    allMissing.slice(4, 6),
    allMissing.slice(6)
  ];

  const activities = [
    "Learn the basics and practise simple exercises.",
    "Continue learning and solve beginner practice problems.",
    "Use what you learned to build a small project.",
    "Revise, improve your project, and practise explaining your work."
  ];

  for (let i = 0; i < 4; i++) {
    const skills = skillGroups[i];
    let description;

    if (skills.length > 0) {
      description = `Focus on ${skills.join(" and ")}. ${activities[i]}`;
    } else {
      description = activities[i];
    }

    roadmap.push([`Week ${i + 1}`, description]);
  }
}

const roadmapHtml = roadmap.map(([week, description]) => `
  <div class="week">
    <strong>${escapeHtml(week)}</strong>
    <p>${escapeHtml(description)}</p>
  </div>
`).join("");

const projectsHtml = projects.map(project => `
  <li>${escapeHtml(project)}</li>
`).join("");

const skillsAdvice = allMissing.length
  ? `Prioritise learning ${allMissing.slice(0, 3).join(", ")}.`
  : "You have matched all the listed skills across these sample jobs. Practise interviews and strengthen your portfolio.";

const adviceFor = job => {
  const missing = job.missingSkills || [];
  const matched = job.matchedSkills || [];

  if (missing.length === 0) {
    return "You have all the listed skills for this sample job. Practise interview questions and build a project to demonstrate your skills.";
  }

  let advice = `Start by learning ${missing[0]}.`;

  if (missing.length > 1) {
    advice += ` Next, focus on ${missing.slice(1).join(" and ")}.`;
  }

  advice += " Build a small project using these skills and add it to your portfolio.";

  if (matched.length > 0) {
    advice += ` Continue practising ${matched.join(" and ")} too.`;
  }

  return advice;
};

const cards = results.map(job => {
  const percent = Math.max(
    0, Math.min(100, Number(job.matchPercentage) || 0)
  );

  const matched = (job.matchedSkills || []).map(escapeHtml);
  const missing = (job.missingSkills || []).map(escapeHtml);

  return `
    <section class="card">
      <h2>${escapeHtml(job.jobTitle)}</h2>
      <p class="company">${escapeHtml(job.company)}</p>
      <div class="score">${percent}% match</div>
      <div class="track">
        <div class="fill" style="width:${percent}%"></div>
      </div>
      <p><strong>Matched skills:</strong> ${matched.join(", ") || "None"}</p>
      <p><strong>Skills to learn:</strong> ${missing.join(", ") || "None"}</p>
      <div class="advice">
        <strong>Your next steps</strong>
        <p>${escapeHtml(adviceFor(job))}</p>
      </div>
    </section>
  `;
}).join("");

const totalJobs = results.length;

const bestJob = results.reduce((best, job) => {
  if (!best) return job;
  return Number(job.matchPercentage || 0) >
    Number(best.matchPercentage || 0) ? job : best;
}, null);

const highestMatch = bestJob
  ? Math.max(0, Math.min(100, Number(bestJob.matchPercentage) || 0))
  : 0;

const skillsToLearnCount = allMissing.length;

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Your Job Match Report</title>
<style>
  body {
    font-family: Arial, sans-serif;
    max-width: 760px;
    margin: 0 auto;
    padding: 24px;
    background: #f4f7fb;
    color: #172033;
  }
  h1 { margin-bottom: 8px; }
  h2 { margin: 0 0 6px; font-size: 21px; }
  h3 { margin-top: 0; }
  .intro { color: #596579; margin-bottom: 24px; }
  .card, .roadmap, .projects {
    background: white;
    border: 1px solid #e0e6ef;
    border-radius: 14px;
    padding: 20px;
    margin: 16px 0;
  }
  .company { color: #68758a; margin: 0 0 16px; }
  .score { font-size: 24px; font-weight: bold; color: #16784a; }
  .track {
    background: #e6ebf2;
    height: 9px;
    border-radius: 20px;
    overflow: hidden;
    margin: 10px 0 18px;
  }
  .fill { background: #20a464; height: 100%; }
  .advice {
    background: #eef6ff;
    padding: 14px;
    border-radius: 10px;
    margin-top: 16px;
  }
  .advice p, .week p { margin-bottom: 0; line-height: 1.5; }
  .week {
    border-left: 3px solid #20a464;
    padding: 8px 12px;
    margin: 12px 0;
    background: #f7fafc;
  }
  li { line-height: 1.8; }
  p { line-height: 1.5; }
  footer { color: #68758a; font-size: 12px; margin-top: 24px; }

.dashboard {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin: 20px 0;
}

.stat {
  background: white;
  border: 1px solid #e0e6ef;
  border-radius: 14px;
  padding: 18px;
  min-width: 0;
  box-shadow: 0 3px 10px rgba(23, 32, 51, 0.04);
}

.stat-label {
  color: #68758a;
  font-size: 13px;
  margin-bottom: 8px;
}

.stat-value {
  font-size: 25px;
  font-weight: bold;
  color: #16784a;
  overflow-wrap: anywhere;
}

@media (max-width: 480px) {
  body {
    padding: 14px;
  }

  .dashboard {
    gap: 8px;
  }

  .stat {
    padding: 12px;
  }

  .stat-value {
    font-size: 20px;
  }
}

</style>
</head>
<body>
  <h1>Your Job Match Report</h1>
  <p class="intro">
    Preferred role: ${escapeHtml(preferredRole)}.
    Review your learning plan and job matches below.
  </p>

<div class="dashboard">
  <div class="stat">
    <div class="stat-label">Sample Jobs Analysed</div>
    <div class="stat-value">${totalJobs}</div>
  </div>

  <div class="stat">
    <div class="stat-label">Highest Match</div>
    <div class="stat-value">${highestMatch}%</div>
  </div>

  <div class="stat">
    <div class="stat-label">Best-Matching Job</div>
    <div class="stat-value" style="font-size:17px">
      ${escapeHtml(bestJob?.jobTitle || "No results")}
    </div>
  </div>

  <div class="stat">
    <div class="stat-label">Unique Skills to Learn</div>
    <div class="stat-value">${skillsToLearnCount}</div>
  </div>
</div>

  <section class="roadmap">
    <h3>Your 4-Week Learning Roadmap</h3>
    <p>${escapeHtml(skillsAdvice)}</p>
    ${roadmapHtml}
  </section>

  <section class="projects">
    <h3>Beginner Portfolio Project Ideas</h3>
    <p>Choose one project and build it step by step.</p>
    <ul>${projectsHtml}</ul>
  </section>

  <h2>Job Match Results</h2>
  ${cards}

  <footer>
    These are sample job profiles, not live vacancies.
    Match percentages use the listed skills only.
    Learning plans and recommendations are generated using
    programmed rules, not a generative AI model.
  </footer>
</body>
</html>`;

return [{ json: { resultHtml: html } }];
